// Flujo simplificado
// 1. Spring valida firma JWT via JWKS → token confiable
// 2. JwtAuthenticationConverter recibe el Jwt validado
// 3. Extrae claims de roles/permisos
// 4. Crea JwtAuthenticationToken con GrantedAuthorities
// 5. Spring lo pone en el SecurityContext

// JWT de Keycloak — estructura de roles anidada
{
  "realm_access": {
    "roles": ["ROLE_ADMIN", "ROLE_USER"]
  },
  "preferred_username": "admin-user"
}

// JWT de Auth0 — con audience explícito
{
  "iss": "https://dev-xxx.us.auth0.com/",
  "sub": "auth0|6a14b7a114616cbf55e88267",
  "aud": "https://spring-lab-api",
  "permissions": ["admin:data", "read:data"]
}

// Access Token de Cognito
{
  "cognito:groups": ["ADMIN"],
  "username": "a1b2c3d4-uuid",
  "client_id": "5c95rig78..."
  // email NO está aquí
}

// ID Token de Cognito
{
  "email": "admin@example.com",
  "name": "Admin User"
  // datos de identidad
}

// Keycloak — roles con prefijo ROLE_
@PreAuthorize("hasRole('ROLE_ADMIN')")

// Auth0 — permisos resource:action sin prefijo
@PreAuthorize("hasAuthority('admin:data')")

// module-auth0/SecurityConfig.java
OAuth2TokenValidator<Jwt> withIssuer =
    JwtValidators.createDefaultWithIssuer(issuer);

OAuth2TokenValidator<Jwt> audienceValidator =
    token -> token.getAudience().contains(audience)
        ? OAuth2TokenValidatorResult.success()
        : OAuth2TokenValidatorResult.failure(...);

decoder.setJwtValidator(
    new DelegatingOAuth2TokenValidator<>(withIssuer, audienceValidator));

// module-keycloak / auth0 / cognito — siempre presente
.sessionManagement(session -> session
    .sessionCreationPolicy(SessionCreationPolicy.STATELESS))

